//! Short, quiet cues (the port of `AmbientSoundEffects.swift`), generated by `scripts/make-sound-cues.py`.
//! Played here rather than in the bar's page: the bar never takes focus and the shortcut is a global hook, so the
//! webview would have no user gesture to allow audio. Never looped; a new cue stops the one before it.
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};

use ambient_platform::playback::{AudioPlayback, PlayingClip};

use crate::log_line;

/// The files peak at half scale; this keeps every cue well under a spoken reply.
const VOLUME: f32 = 0.18;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SoundCue {
    Listen,
    Send,
    Attention,
    Complete,
    Error,
}

impl SoundCue {
    fn name(self) -> &'static str {
        match self {
            SoundCue::Listen => "listen",
            SoundCue::Send => "send",
            SoundCue::Attention => "attention",
            SoundCue::Complete => "complete",
            SoundCue::Error => "error",
        }
    }

    fn wav(self) -> &'static [u8] {
        match self {
            SoundCue::Listen => include_bytes!("../../src/sounds/listen.wav"),
            SoundCue::Send => include_bytes!("../../src/sounds/send.wav"),
            SoundCue::Attention => include_bytes!("../../src/sounds/attention.wav"),
            SoundCue::Complete => include_bytes!("../../src/sounds/complete.wav"),
            SoundCue::Error => include_bytes!("../../src/sounds/error.wav"),
        }
    }
}

pub struct SoundEffects {
    is_enabled: Arc<AtomicBool>,
    playing: Arc<Mutex<Option<PlayingClip>>>,
}

impl SoundEffects {
    pub fn new() -> Self {
        Self { is_enabled: Arc::new(AtomicBool::new(true)), playing: Arc::new(Mutex::new(None)) }
    }

    /// Turning cues off also silences one that is playing.
    pub fn set_enabled(&self, is_enabled: bool) {
        self.is_enabled.store(is_enabled, Ordering::SeqCst);
        if !is_enabled {
            if let Some(mut clip) = self.playing.lock().unwrap().take() {
                clip.stop();
            }
        }
    }

    /// Opening the output device takes a moment, so it happens off the caller's thread. A cue that cannot play is
    /// only logged: it is never worth an error in the bar.
    pub fn play(&self, cue: SoundCue) {
        if !self.is_enabled.load(Ordering::SeqCst) {
            return;
        }
        let (is_enabled, playing) = (self.is_enabled.clone(), self.playing.clone());
        std::thread::spawn(move || {
            let mut playing = playing.lock().unwrap();
            if let Some(mut clip) = playing.take() {
                clip.stop();
            }
            // Turned off while this thread was starting.
            if !is_enabled.load(Ordering::SeqCst) {
                return;
            }
            match AudioPlayback::play(cue.wav().to_vec(), VOLUME) {
                Ok(clip) => {
                    *playing = Some(clip);
                    log_line(&format!("sound cue: {}", cue.name()));
                }
                Err(error) => log_line(&format!("sound cue {} could not play: {error}", cue.name())),
            }
        });
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_cue_is_a_bundled_wave_file() {
        for cue in [SoundCue::Listen, SoundCue::Send, SoundCue::Attention, SoundCue::Complete, SoundCue::Error] {
            let wav = cue.wav();
            assert!(wav.len() > 44, "{} is empty", cue.name());
            assert_eq!(&wav[0..4], b"RIFF", "{}", cue.name());
            assert_eq!(&wav[8..12], b"WAVE", "{}", cue.name());
        }
    }
}
